function getLocalWeekday(dateStr, timeStr, timeZone) {
  const d = getUtcFromLocal(dateStr, timeStr || '12:00', timeZone);
  const dayStr = new Intl.DateTimeFormat('en-US', { timeZone, weekday: 'short' }).format(d);
  const map = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
  return map[dayStr];
}

const prev = $input.item.json;
const active = prev.active_confirmed;
const doc = prev.doctor || {};
const tz = doc.timezone || 'Asia/Kolkata';
const wh = doc.working_hours || { start: "09:00", end: "17:00" };
const workingDays = doc.working_days || [1, 2, 3, 4, 5, 6];
const slotDuration = doc.slot_duration_minutes || 30;
const cutoffMin = doc.booking_cutoff_minutes || 60;
const unavailList = prev.active_unavailability || [];

if (!active) {
  return [{
    json: {
      ...prev,
      can_reschedule: false,
      error_msg: "You do not have an active confirmed appointment to reschedule. Reply with a date and time to book a new appointment."
    }
  }];
}

if (!prev.requested_date || !prev.requested_time) {
  const currentStart = formatInTimezone(new Date(active.start_time), tz, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
  return [{
    json: {
      ...prev,
      can_reschedule: false,
      error_msg: `Your current appointment (#${active.appointment_id}) is scheduled for ${currentStart}.\n\nPlease reply with your new requested date and time (e.g. 'Reschedule to tomorrow at 3 PM').`
    }
  }];
}

// Full booking rules validation for Reschedule (Bug #9, #36)
const newStartUtc = getUtcFromLocal(prev.requested_date, prev.requested_time, tz);
const newEndUtc = new Date(newStartUtc.getTime() + slotDuration * 60000);

let canResched = true;
let errorMsg = '';

const localDayOfWeek = getLocalWeekday(prev.requested_date, prev.requested_time, tz);
if (!workingDays.includes(localDayOfWeek)) {
  canResched = false;
  errorMsg = `Sorry, ${doc.doctor_name} is closed on that day.`;
} else {
  const [startH, startM] = wh.start.split(':').map(Number);
  const [endH, endM] = wh.end.split(':').map(Number);
  const [reqH, reqM] = prev.requested_time.split(':').map(Number);
  const reqMin = reqH * 60 + reqM;
  if (reqMin < startH * 60 + startM || reqMin + slotDuration > endH * 60 + endM) {
    canResched = false;
    errorMsg = `Operating hours are ${wh.start} to ${wh.end}. The requested time is outside working hours.`;
  }
}

const now = new Date();
if (newStartUtc.getTime() < now.getTime() + cutoffMin * 60000) {
  canResched = false;
  errorMsg = `Rescheduling must be done at least ${cutoffMin} minutes in advance.`;
}

// Doctor leave check
for (const u of unavailList) {
  if (u.doctor_id === doc.doctor_id) {
    const uStart = new Date(u.start_time);
    const uEnd = new Date(u.end_time);
    if (newStartUtc < uEnd && newEndUtc > uStart) {
      canResched = false;
      errorMsg = `Doctor is unavailable on that date (${u.reason || 'Leave'}).`;
      break;
    }
  }
}

return [{
  json: {
    ...prev,
    can_reschedule: canResched,
    error_msg: errorMsg,
    appointment_id: active.appointment_id,
    calendar_event_id: active.calendar_event_id,
    calendar_id: doc.calendar_id || active.calendar_id,
    new_start_iso: newStartUtc.toISOString(),
    new_end_iso: newEndUtc.toISOString()
  }
}];

const prev = $('Validate_Reschedule_Request').first().json;
const gcalItems = $input.all().map(i => i.json).filter(j => j.id || j.start);

const reqStart = new Date(prev.new_start_iso);
const reqEnd = new Date(prev.new_end_iso);

let isFree = true;
for (const ev of gcalItems) {
  if (prev.calendar_event_id && ev.id === prev.calendar_event_id) continue;
  const evStart = new Date(ev.start?.dateTime || ev.start?.date);
  const evEnd = new Date(ev.end?.dateTime || ev.end?.date);
  if (reqStart < evEnd && reqEnd > evStart) {
    isFree = false;
    break;
  }
}

return [{ json: { ...prev, is_reschedule_slot_free: isFree } }];

